class Diagnostic(object):
    """
    The class corresponding to diagnostic page on selenium_coam web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        self._status = StatusPage(driver)
        self._test_clocks = TestClocksPage(driver)
        self._ip_connectivity_test = IPConnectivityTestPage(driver)
        self._sfp_monitoring = SfpMonitoringPage(driver)
        self._downlink = TestModels5GDownlinkPage(driver)
        self._uplink = TestModels5GUplinkPage(driver)
        self._snapshot = SnapshotPage(driver, download_checker)
        self._pmtu_discovery = PmtuDiscoveryPage(driver)
        self._reset_to_test_dedicated_state = ResetToTestDedicatedStatePage(driver)
        self._debug_tracing = DebugTracingPage(driver)

    @property
    def status(self):
        return self._status

    @property
    def test_clocks(self):
        return self._test_clocks

    @property
    def ip_connectivity_test(self):
        return self._ip_connectivity_test

    @property
    def sfp_monitoring(self):
        return self._sfp_monitoring

    @property
    def downlink(self):
        return self._downlink

    @property
    def uplink(self):
        return self._uplink

    @property
    def snapshot(self):
        return self._snapshot

    @property
    def pmtu_discovery(self):
        return self._pmtu_discovery

    @property
    def reset_to_test_dedicated_state(self):
        return self._reset_to_test_dedicated_state

    @property
    def debug_tracing(self):
        return self._debug_tracing


class IPConnectivityTestPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Diagnostic', 'IP Connectivity Test']

    def __init__(self, driver):
        super(IPConnectivityTestPage, self).__init__(driver)
        self._view_panel = IPConnectivityTestPageViewPanel(driver)

    def start_ip_connectivity_test(self, scope, address=None, source_address=None, payload_size=16,
                                   dscp=10, timeout=10):
        """
        Keyword for starting ip connectivity test
        :param scope: str, scope value, default is None
        :param address: str, address value, default is None
        :param source_address: str, source address value, default is None
        :param payload_size: int, payload size, default is 16
        :param dscp: int, dscp value, default is 10
        :param timeout: int, timeout
        """
        self._view_panel.start_ip_connectivity_test(scope, address, source_address, payload_size, dscp, timeout)

    def stop_ip_connectivity_test(self, timeout=10):
        """
        Keyword for stopping ip connectivity test, should never be called before start ip connectivity test
        :param timeout: int, timeout
        """
        self._view_panel.stop_ip_connectivity_test(timeout)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class IPConnectivityTestPageViewPanel(ViewPanel):
    _SCOPE_DROPDOWN_LIST_BUTTON_XPATH = '//label[contains(text(), "Scope")]/parent::*//button'
    _SCOPE_DROPDOWN_LIST_OPTIONS_XPATH = '//label[contains(text(), "Scope")]/parent::*//ul//li'
    _ADDRESS_INPUT_XPATH = '//label[contains(text(), "Address")]/parent::*//input'
    _SOURCE_ADDERSS_BUTTON_XPATH = '//label[contains(text(), "Source address")]/parent::*//button'
    _SOURCE_ADDERSS_OPTIONS_XPATH = '//label[contains(text(), "Source address")]/parent::*//ul//li'
    _PALOAD_SIZE_INPUT_XPATH = '//label[contains(text(), "Payload size")]/parent::*//input'
    _DSCP_INPUT_XPATH = '//label[contains(text(), "DSCP")]/parent::*//input'
    _START_BUTTON_XPATH = '//ip-connectivity-info-table//ui-button[contains(*, "Start")]'
    _STOP_BUTTON_XPATH = '//ip-connectivity-info-table//ui-button[contains(*, "Stop")]'

    def __init__(self, driver):
        super(IPConnectivityTestPageViewPanel, self).__init__(driver)

    def _input_address(self, address, timeout=10):
        if address:
            try:
                self.insert_text_to_enable_element((By.XPATH, self._ADDRESS_INPUT_XPATH), address, timeout)
            except TimeoutException:
                logging.error('Address does not support input now')
                raise

    def _select_source_address(self, source_address, timeout=10):
        if source_address:
            try:
                self.select_element_from_dropdown_list_by_text_and_click(
                    source_address,
                    (By.XPATH, self._SOURCE_ADDERSS_BUTTON_XPATH),
                    (By.XPATH, self._SOURCE_ADDERSS_OPTIONS_XPATH),
                    timeout
                )
            except TimeoutException:
                logging.error('Source address is unclickable now')
                raise

    def start_ip_connectivity_test(self, scope, address=None, source_address=None, payload_size=16,
                                   dscp=10, timeout=10):
        """
        Keyword for starting ip connectivity test
        """
        self.select_element_from_dropdown_list_by_text_and_click(
            scope,
            (By.XPATH, self._SCOPE_DROPDOWN_LIST_BUTTON_XPATH),
            (By.XPATH, self._SCOPE_DROPDOWN_LIST_OPTIONS_XPATH),
            timeout
        )
        self._input_address(address, timeout)
        self._select_source_address(source_address, timeout)
        self.insert_text_to_enable_element((By.XPATH, self._PALOAD_SIZE_INPUT_XPATH), payload_size, timeout)
        self.insert_text_to_enable_element((By.XPATH, self._DSCP_INPUT_XPATH), dscp, timeout)

        self.click_enabled_element((By.XPATH, self._START_BUTTON_XPATH), timeout)

    def stop_ip_connectivity_test(self, timeout=10):
        """
        Keyword for stopping ip connectivity test, should never be called before start ip connectivity test
        """
        self.click_enabled_element((By.XPATH, self._STOP_BUTTON_XPATH), timeout)


