class SfpMonitoringPageViewPanel(ViewPanel):
    _APPLIED_SFP_TITLE = 'SFPs applied to current BTS HW connection'
    _APPLIED_SFP_TABLE_FIRST_TD_XPATH = ('//sfp-table//*[contains(text(), "SFPs applied to current BTS HW connection")]'
                                         '/following-sibling::div[1]//table[contains(@class, '
                                         '"sfp-monitoring-inner-table")]/tbody/child::tr[1]/td[1]')
    _NOT_APPLIED_SFP_TITLE = 'SFPs not applied to current BTS HW connection'
    _NOT_APPLIED_SFP_TABLE_FIRST_TD_XPATH = ('//sfp-table//*[contains(text(), "SFPs not applied to current BTS HW '
                                             'connection")]/following-sibling::div[1]//table[contains(@class, '
                                             '"sfp-monitoring-inner-table")]/tbody/child::tr[1]/td[1]')

    def _format_data_by_rowspan(self, trs_rowspan_list, trs_value_list):
        """
        Param "trs_rowspan_list" is a list that contains all value of "rowspan" attribute in "td" label from "tr" labels
        Param "trs_value_list" is a list that contains all value of "td" label from "tr" labels

        "trs_rowspan_list" is like as below:
        [[a0(rows=4), b0(rows=8), c0(rows=4), d0(rows=4), e0(rows=1), f0(rows=1), g0(rows=1), h0(rows=1), i0(rows=4)],
         [e1, f1, g1, h1],  --> all elements that do not exist in this line will be migrated from first line
         [e2, f2, g2, h2],  --> same as above
         [e3, f3, g3, h3],  --> as above
         [a4(rows=4), c4(rows=4), d4(rows=4), e4(rows=1), f4(rows=1), g4(rows=1), h4(rows=1), i4(rows=4)],
                            --> the number "8" in first line will be inserted in this line on index "1"
         [e5, f5, g5, h5],  --> all elements that do not exist in this line will be migrated from fifth line
         [e6, f6, g6, h6],  --> same as above
         [e7, f7, g7, h7]]  --> same as above

         After data format, "trs_rowspan_list" will be like a matrix as below:
        [[a0, b0, c0, d0, e0, f0, g0, h0, i0],
         [a0, b0, c0, d0, e1, f1, g1, h1, i0],
         [a0, b0, c0, d0, e2, f2, g2, h2, i0],
         [a0, b0, c0, d0, e3, f3, g3, h3, i0],
         [a4, b0, c4, d4, e4, f4, g4, h4, i4],
         [a4, b0, c4, d4, e5, f5, g5, h5, i4],
         [a4, b0, c4, d4, e6, f6, g6, h6, i4],
         [a4, b0, c4, d4, e7, f7, g7, h7, i4]]

         All elements in "trs_value_list" will be format by "trs_rowspan_list".
        """
        first_rowspan = trs_rowspan_list[0]
        trs_values = copy.deepcopy(trs_value_list)
        first_tr_value = trs_values[0]

        for index, rowspan in enumerate(trs_rowspan_list[1:]):
            start = first_rowspan.index(rowspan[0])
            end = start + len(rowspan)

            if first_rowspan[start: end] == rowspan:
                for value in first_tr_value[:start][::-1]:
                    trs_values[index + 1].insert(0, value)
                trs_values[index + 1].extend(first_tr_value[end:])
            else:
                max_rowspan_index = first_rowspan.index(max(first_rowspan))
                rowspan.insert(max_rowspan_index, max(first_rowspan))

                tr_value = trs_values[index + 1]
                tr_value.insert(max_rowspan_index, first_tr_value[max_rowspan_index])

                first_tr_value = tr_value
                first_rowspan = rowspan
        return trs_values

    def _get_rowspan_and_tr_value(self, tr_xpath):
        trs_rowspan_list = []
        trs_value_list = []
        for index, tr_elem in enumerate(self.driver.find_elements_by_xpath(tr_xpath)):
            rowspan_list, value_list = [], []
            for td_elem in tr_elem.find_elements_by_xpath('td'):
                rowspan = td_elem.get_attribute('rowspan')
                rowspan_list.append(int(rowspan) if rowspan else 1)

                value_list.append(td_elem.text)
            trs_rowspan_list.append(rowspan_list)
            trs_value_list.append(value_list)
        return trs_rowspan_list, trs_value_list

    def _filter_sfps(self, sfps_info, filter_dict):
        if not filter_dict:
            return sfps_info

        result = []
        for sfp in sfps_info:
            if all([sfp.get(k) == v for k, v in filter_dict.items()]):
                result.append(sfp)
        return result

    def _get_sfps_info(self, sfp_title, filter_dict, timeout):
        _sfp_base_xpath = '//sfp-table//*[contains(text(), "{}")]/following-sibling::div[1]'.format(sfp_title)
        _sfp_table_head_xpath = _sfp_base_xpath + '//table[contains(@class, "sfp-monitoring-outer-table")]/thead//th'
        _sfp_outer_table_tr_xpath = _sfp_base_xpath + '/table/tbody/child::tr'
        _sfp_inner_table_tr_xpath = _sfp_base_xpath + ('/table/tbody/child::tr[{}]//table[contains(@class, '
                                                       '"sfp-monitoring-inner-table")]/tbody/child::tr')

        head_value = self.get_fields_info_from_row(_sfp_table_head_xpath, timeout)
        sfps_info = []
        outer_table_trs_length = len(self.driver.find_elements_by_xpath(_sfp_outer_table_tr_xpath))
        for index in range(1, outer_table_trs_length + 1):
            trs_rowspan_list, trs_value_list = self._get_rowspan_and_tr_value(_sfp_inner_table_tr_xpath.format(index))
            value_list = self._format_data_by_rowspan(trs_rowspan_list, trs_value_list)
            for tr_value in value_list:
                sfps_info.append(dict(zip(head_value, tr_value)))

        return self._filter_sfps(sfps_info, filter_dict)

    def get_applied_sfps_info(self, filter_dict=None, timeout=60):
        return self._get_sfps_info(self._APPLIED_SFP_TITLE, filter_dict, timeout)

    def get_not_applied_sfps_info(self, filter_dict=None, timeout=60):
        return self._get_sfps_info(self._NOT_APPLIED_SFP_TITLE, filter_dict, timeout)


class SfpMonitoringPageDetailPanel(DetailPanel):
    _SFP_DETAIL_XPATH = '//details-panel//sfp-details//ui-table//table'
    _SFP_DETAIL_MODULE_BASE_XPATH = '//details-panel//sfp-details'
    _SFP_DETAIL_MODULE_TITLES_XPATH = _SFP_DETAIL_MODULE_BASE_XPATH + '//h5'
    _SFP_DETAIL_MODULE_SPECIFIC_TITLE_XPATH = _SFP_DETAIL_MODULE_TITLES_XPATH + '[contains(text(), "{}")]'
    _MAX_TRANSMISSION_DISTANCE = "Max Transmission Distance"

    def __init__(self, driver):
        super(SfpMonitoringPageDetailPanel, self).__init__(driver)

    def _get_head_values(self, table_title_xpath):
        if self._MAX_TRANSMISSION_DISTANCE in table_title_xpath:
            _MODULE_HEAD_VALUE_XPATH = table_title_xpath + '/following-sibling::ui-table[1]//thead//tr[last()]//th'
            head_values = self.get_fields_info_from_row(_MODULE_HEAD_VALUE_XPATH, 60)
        else:
            _MODULE_HEAD_VALUE_XPATH = table_title_xpath + '/following-sibling::ui-table[1]//thead//th'
            head_values = self.get_fields_info_from_row(_MODULE_HEAD_VALUE_XPATH, 60)[1:]
        return head_values

    def _get_detail_panel_table_info(self, table_title_xpath):
        head_values = self._get_head_values(table_title_xpath)
        table_info = {head_value: {} for head_value in head_values}

        _MODULE_BODY_TR_XPATH = table_title_xpath + '/following-sibling::ui-table[1]//tbody//tr'
        for tr_elem in self.driver.find_elements_by_xpath(_MODULE_BODY_TR_XPATH):
            td_elems = tr_elem.find_elements_by_xpath('.//td')
            td_values = [{td_elems[0].text: elem.text} for elem in td_elems[1:]]

            if len(head_values) != len(td_values):
                try:
                    td_value = td_values[-1]
                    td_values.append(td_value)
                except IndexError:
                    continue

            for index, key in enumerate(table_info):
                table_info[key].update(td_values[index])
        return table_info

    def _get_sfp_detail_module_titles(self, timeout):
        return self.get_fields_info_from_row(self._SFP_DETAIL_MODULE_TITLES_XPATH, timeout)

    def get_sfps_detailed_info(self, sfp_module, port, parameter, timeout):
        sfps_detail_info = {}
        for title in self._get_sfp_detail_module_titles(timeout):
            info = self._get_detail_panel_table_info(self._SFP_DETAIL_MODULE_SPECIFIC_TITLE_XPATH.format(title))
            sfps_detail_info.update({title: info})

        if not sfp_module and not port and not parameter:
            return sfps_detail_info
        elif sfp_module and not port and not parameter:
            return sfps_detail_info[sfp_module]
        elif sfp_module and port and not parameter:
            return sfps_detail_info[sfp_module][port]
        elif sfp_module and port and parameter:
            return sfps_detail_info[sfp_module][port][parameter]
        else:
            logging.warning('please check value of sfp_module, port, parameter these params')
            return {}


