class TestModelsPageViewPanel(ViewPanel):
    _LOCAL_CELL_DROPDOWN_LIST_BUTTON_XPATH = '//div[contains(text(), "Local cell:")]/parent::*//button'
    _LOCAL_CELL_DROPDOWN_LIST_OPTIONS_XPATH = '//div[contains(text(), "Local cell:")]/parent::*//ul//li'
    _PHYSICAL_CELL_ID_INPUT_XPATH = '//div[contains(text(), "Physical cell ID:")]/parent::*//input'
    _START_TEST_BUTTON_XPATH = '//button[contains(text(), "Start Test")]'
    _STOP_TEST_BUTTON_XPATH = '//div[contains(text(), "Tests")]/parent::*/parent::*//tr[{}]//ui-button'
    _CARRIER_FREQUENCY_VALUE_LABEL_XPATH = '//div[contains(text(), "Carrier frequency:")]/parent::*//span'
    _TESTS_TABLE_ROW_XPATH = '//div[contains(text(), "Tests")]/parent::*/parent::*//tr[{}]/td[1]'
    _TEST_TABLE_PROGRESS_CELL_XPATH = '//div[contains(text(), "Tests")]/parent::*/parent::*//tr[{}]/td[3]'
    _SAVE_TEST_RESULTS_BUTTON_XPATH = '//button[contains(text(), "Save Test Results")]'

    def __init__(self, driver):
        super(TestModelsPageViewPanel, self).__init__(driver)

    def wait_for_test_to_start(self, test_id, timeout):
        """
        Waits for test to be successfully started.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        """
        self._check_test_id(test_id)
        self.wait_for_text_present_in_element((By.XPATH, self._TEST_TABLE_PROGRESS_CELL_XPATH.format(test_id)),
                                              'Start test succeed and test is ongoing.', timeout)

    def stop_test(self, test_id, timeout):
        """
        Stops 5G downlink test.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        """
        self._check_test_id(test_id)
        self.click_enabled_element_after_visible((By.XPATH, self._STOP_TEST_BUTTON_XPATH.format(test_id)), timeout)

    def wait_for_test_to_stop(self, test_id, timeout):
        """
        Waits for test to be successfully stopped.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        """
        self._check_test_id(test_id)
        self.wait_for_text_present_in_element((By.XPATH, self._TEST_TABLE_PROGRESS_CELL_XPATH.format(test_id)),
                                              'Stop succeed.', timeout)

    def get_carrier_frequency(self, timeout):
        """
        Gets value of carrier frequency.
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        :return: value of carrier frequency if is available, None otherwise
        :rtype: float
        """
        carrier_freq = self.get_text_by_xpath(self._CARRIER_FREQUENCY_VALUE_LABEL_XPATH, timeout)
        carrier_freq = carrier_freq.split(' ')[0]
        carrier_freq = carrier_freq.replace(',', '')
        return float(carrier_freq) if carrier_freq else None

    @staticmethod
    def _check_test_id(test_id):
        if test_id < 1:
            raise ValueError("Test ID can't be lower then 1 but it was {}".format(test_id))

    def _select_test_from_table(self, test_id, timeout):
        self._check_test_id(test_id)
        self.click_enabled_element_after_visible((By.XPATH, self._TESTS_TABLE_ROW_XPATH.format(test_id)), timeout)


