    _POLARIZATION_DROPDOWN_LIST_OPTIONS_XPATH = '//div[contains(text(), "Polarization:")]/parent::*//ul//li'
    _P_MAX_INPUT_XPATH = '//div[contains(text(), "pMax:")]/parent::*//input'
    _TESTS_TABLE_ROW_BY_CELL_AND_MODEL_XPATH = ('//div[contains(text(), "Tests")]/parent::*/parent::*'
                                                '//td[text()="{}"]/parent::*//td[text()="{}"]')
    _EXTERNAL_EQUIPMENT_RESULT_INPUT_XPATH = ('//p[contains(text(), "Test result from external measuring equipment")]'
                                              '/parent::*//textarea')

    def __init__(self, driver):
        super(TestModels5GDownlinkPageViewPanel, self).__init__(driver)

    def _configure_downlink_test(self, local_cell, test_model, p_max, timeout, polarization, physical_cell_id):
        self.select_element_from_dropdown_list_by_text_and_click(
            local_cell,
            (By.XPATH, self._LOCAL_CELL_DROPDOWN_LIST_BUTTON_XPATH),
            (By.XPATH, self._LOCAL_CELL_DROPDOWN_LIST_OPTIONS_XPATH),
            timeout
        )

        self.select_element_from_dropdown_list_by_text_and_click(
            test_model,
            (By.XPATH, self._TEST_MODEL_DROPDOWN_LIST_BUTTON_XPATH),
            (By.XPATH, self._TEST_MODEL_DROPDOWN_LIST_OPTIONS_XPATH),
            timeout
        )

        if polarization is not None:
            self.select_element_from_dropdown_list_by_text_and_click(
                polarization,
                (By.XPATH, self._POLARIZATION_DROPDOWN_LIST_BUTTON_XPATH),
                (By.XPATH, self._POLARIZATION_DROPDOWN_LIST_OPTIONS_XPATH),
                timeout
            )

        self.insert_text_to_enable_element((By.XPATH, self._P_MAX_INPUT_XPATH), str(p_max), timeout)

        if physical_cell_id is not None:
            self.insert_text_to_enable_element((By.XPATH, self._PHYSICAL_CELL_ID_INPUT_XPATH),
                                               str(physical_cell_id),
                                               timeout)

    def start_test(self, local_cell, test_model, p_max, timeout, polarization, physical_cell_id):
        """
        Starts 5G downlink test.
        :param local_cell: name of local cell for which test will be started
        :type local_cell: str
        :param test_model: name of test model which will be used during test
        :type test_model: str
        :param p_max: value of pMax which will be used during test
        :type p_max: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        :param polarization: value of Polarization which will be used during test
        :type polarization: str
        :param physical_cell_id: value of Physical cell ID which will be used during test
        :type physical_cell_id: int
        """

        self._configure_downlink_test(local_cell, test_model, p_max, timeout, polarization, physical_cell_id)

        self.click_enabled_element((By.XPATH, self._START_TEST_BUTTON_XPATH), timeout)

    def save_test_results(self, test_id, external_equipment_result, timeout):
        """
        Saves results of 5G downlink test.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param external_equipment_result: text which will be typed into 'Test result from external measuring equipment'
                                          before saving test results
        :type external_equipment_result: str
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        """
        self._select_test_from_table(test_id, timeout)
        if external_equipment_result:
            self.insert_text_to_enable_element((By.XPATH, self._EXTERNAL_EQUIPMENT_RESULT_INPUT_XPATH),
                                               external_equipment_result, timeout)
            time.sleep(1)
        self.click_enabled_element((By.XPATH, self._SAVE_TEST_RESULTS_BUTTON_XPATH), timeout)

    def is_test_available(self, local_cell, test_model, timeout):
        """
        Checks whether test is visible in Tests table.
        :param local_cell: name of local cell which checked test should contain
        :type local_cell: str
        :param test_model: name of test model which checked test should contain
        :type test_model: str
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        :return: True if test with given local cell and test model is available, False otherwise
        :rtype: bool
        """
        try:
            self.wait_for_visibility_by_xpath(
                self._TESTS_TABLE_ROW_BY_CELL_AND_MODEL_XPATH.format(local_cell.split('-')[1], test_model), timeout)
        except TimeoutException:
            return False
        return True


