class PmtuDiscoveryPageViewPanel(ViewPanel):
    SOURCE_IP_DROP_DOWN_BUTTON_XPATH = '//label[contains(text(), "Source IP address")]/parent::div//button'
    SOURCE_IP_OPTION_IP_XPATH = '//label[contains(text(), "Source IP address")]/parent::div//ul//span'
    DESTINATION_IP_INPUT_XPATH = '//label[contains(text(), "Destination IP address")]/parent::div//input'
    DSCP_INPUT_XPATH = '//label[contains(text(), "DSCP")]/parent::div//input'
    START_BUTTON_XPATH = '//button[contains(text(), "Start")]'
    PMTU_DISCOVERY_STATUS_XPATH = '//span[contains(text(), "PMTU discovery")]'
    MAX_TRANS_COMMON_XAPTH = '/parent::div//span[contains(@class, "pmtu-discover-result-number")]'
    PATH_MAX_TRANS_UNIT_XPATH = '//label[contains(@id, "pmtu-discover-result-pmtu-label")]' + MAX_TRANS_COMMON_XAPTH
    LOCAL_MAX_TRANS_UNIT_XPATH = '//label[contains(@id, "pmtu-discover-result-lmtu-label")]' + MAX_TRANS_COMMON_XAPTH

    def __init__(self, driver):
        super(PmtuDiscoveryPageViewPanel, self).__init__(driver)

    def start_pmtu_discovery(self, source_ip, destination_ip, dscp, timeout=90):
        self.select_element_from_dropdown_list_by_text_and_click(source_ip,
                                                                 (By.XPATH, self.SOURCE_IP_DROP_DOWN_BUTTON_XPATH),
                                                                 (By.XPATH, self.SOURCE_IP_OPTION_IP_XPATH),
                                                                 timeout)
        self.insert_text_to_enable_element((By.XPATH, self.DESTINATION_IP_INPUT_XPATH), destination_ip, timeout)
        self.insert_text_to_enable_element((By.XPATH, self.DSCP_INPUT_XPATH), dscp, timeout)
        self.click_and_wait_for_corresponding_element_visible(self.START_BUTTON_XPATH,
                                                              self.PMTU_DISCOVERY_STATUS_XPATH, timeout=timeout)
        status = self.get_text_by_xpath(self.PMTU_DISCOVERY_STATUS_XPATH, timeout)
        path_value = self.get_text_by_xpath(self.PATH_MAX_TRANS_UNIT_XPATH, timeout)
        local_value = self.get_text_by_xpath(self.LOCAL_MAX_TRANS_UNIT_XPATH, timeout)
        return [path_value, local_value, status]


